      const x = Math.cos(a) * R;
      const z = Math.sin(a) * R;
      const r = rr0 * (1 - Math.pow(t, 0.8)) + 0.05;
      const lift = 1.4 * Math.pow(1 - t, 1.2) - 0.9 * t * t;
      pts.push([x, moundH(x, z) + r * lift, z]);
    }
    roots.push({ name: `root-${k}`, level: 1, pts, r0: rr0 + 0.05, r1: 0.05 });
